((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
globalThis.KENGURU_GRADES_7_8 = [{"id":"2012-9-10","year":2012,"grades":[9,10],"label":"9–10 классы","tasksUrl":"assets/kenguru/kenguru_2012_class_9-10.pdf","answersUrl":"assets/kenguru/kenguru_2012_answers.pdf","solutionUrl":null,"answerLetters":"АБВГД","cards":[{"number":1,"title":"Бабочка и кенгуру","question":"Бабочку отразили зеркально относительно прямой b, а потом повернули на 90° против часовой стрелки вокруг кончика носа кенгуру (точки A). После этого бабочка оказалась у кенгуру","options":[{"text":"на носу"},{"text":"на лапе"},{"text":"на хвосте"},{"text":"на спине"},{"text":"в сумке"}],"condition":{"src":"assets/grades-9-10/2012/task-01.svg","width":261,"height":159,"pixelWidth":362,"pixelHeight":220,"alt":"Кенгуру стоит слева от вертикальной прямой b, бабочка находится справа от неё и выше кончика носа A"},"answer":3,"points":3,"review":[{"title":"Решение","text":"Отражение переносит бабочку на другую сторону прямой b, сохраняя её высоту. На рисунке она оказывается левее точки A и выше неё."},{"title":"Ответ","text":"Поворот против часовой стрелки на четверть оборота переносит точку из верхнего левого угла относительно A в нижний левый. В результате бабочка окажется у кенгуру на спине."}],"keyNote":null},{"number":2,"title":"Цифры семизначного числа","question":"Сумма цифр семизначного числа равна 6. Чему равно произведение цифр этого числа?","options":[{"text":"0"},{"text":"5"},{"text":"6"},{"text":"7"},{"text":"невозможно определить"}],"condition":null,"answer":0,"points":3,"review":[{"title":"Решение","text":"Если бы все семь цифр были ненулевыми, их сумма была бы не меньше 7."},{"title":"Ответ","text":"Сумма 6 означает наличие нуля. Поэтому произведение цифр равно 0."}],"keyNote":null},{"number":3,"title":"Треугольники по углам","question":"Сколько существует различных треугольников, у которых одна из сторон равна 1, а два угла равны 40° и 70°?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"0"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Решение","text":"Третий угол равен 180° − 40° − 70° = 70°. Значит, треугольник равнобедренный, а его форма по углам определена."},{"title":"Ответ","text":"Длину 1 может иметь либо основание напротив 40°, либо одна из двух одинаковых боковых сторон. По одному масштабу на каждый случай, всего два."}],"keyNote":null},{"number":4,"title":"Копейки и приставки","question":"Сколько копеек в децисантикилорубле?","options":[{"text":"0,1"},{"text":"1"},{"text":"10"},{"text":"100"},{"text":"1000"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"Приставки «деци», «санти» и «кило» означают умножение на 1/10, 1/100 и 1000. Их произведение равно 1."},{"title":"Ответ","text":"Получается один рубль, в нём 100 копеек."}],"keyNote":null},{"number":5,"title":"Уровень воды в Венеции","question":"В Венеции каждый день происходит небольшое наводнение: вода поднимается, а потом отступает. На графике показано изменение уровня воды 6 мая 2011 года. Сколько часов в этот день уровень воды был выше 30 см?","options":[{"text":"5"},{"text":"6"},{"text":"7"},{"text":"9"},{"text":"12"}],"condition":{"src":"assets/grades-9-10/2012/task-05.svg","width":754,"height":278,"pixelWidth":1048,"pixelHeight":385,"alt":"График уровня воды в сантиметрах по времени в часах. Уровень пересекает отметку 30 см в 3, 11, 17 и 21 час"},"answer":4,"points":3,"review":[{"title":"Решение","text":"По графику уровень выше 30 см с 3 до 11 часов, а затем с 17 до 21 часа."},{"title":"Ответ","text":"Суммарно это (11 − 3) + (21 − 17) = 12 часов."}],"keyNote":null},{"number":6,"title":"Куб и квадрат степеней","question":"Число, куб которого равен 2012¹², умножили на квадрат числа 2012¹¹. Что получилось?","options":[{"text":"2012²¹"},{"text":"2012²⁶"},{"text":"2012³¹"},{"text":"2012⁵⁸"},{"text":"2012⁸⁸"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Решение","text":"Кубический корень из 2012¹² равен 2012⁴. Квадрат числа 2012¹¹ равен 2012²²."},{"title":"Ответ","text":"При умножении показатели складываются. Получаем 2012²⁶."}],"keyNote":null},{"number":7,"title":"Линия движения жука","question":"Жук Жак ползёт по координатной плоскости. Он стартует из точки (1; 1) и движется так, что произведение его координат не меняется. По какой линии ползёт жук?","options":[{"text":"по прямой"},{"text":"по окружности"},{"text":"по параболе"},{"text":"по гиперболе"},{"text":"по ломаной линии"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"В начальной точке произведение координат равно 1. Значит, в каждой точке пути xy = 1."},{"title":"Ответ","text":"Это график y = 1/x, то есть гипербола. Жук движется по её ветви в первой четверти."}],"keyNote":null},{"number":8,"title":"Минутная стрелка","question":"Часы лежат на столе циферблатом вверх. Минутная стрелка сейчас указывает на юго-восток. Через сколько минут она будет указывать на северо-восток?","options":[{"text":"15"},{"text":"20"},{"text":"30"},{"text":"40"},{"text":"45"}],"condition":null,"answer":4,"points":3,"review":[{"title":"Решение","text":"По часовой стрелке после юго-востока идут юг, юго-запад, запад, северо-запад, север и северо-восток. Это три четверти оборота."},{"title":"Ответ","text":"На полный оборот минутной стрелки уходит час. Нужно 45 минут."}],"keyNote":null},{"number":9,"title":"Ложка дёгтя","question":"Как гласит русская поговорка, ложка дёгтя портит бочку мёда. Сколько банок мёда удастся испортить десятью каплями дёгтя, если в бочке 40 банок, а в ложке 200 капель?","options":[{"text":"2"},{"text":"4"},{"text":"5"},{"text":"10"},{"text":"20"}],"condition":null,"answer":0,"points":3,"review":[{"title":"Решение","text":"Двести капель портят 40 банок, то есть на одну банку приходится пять капель."},{"title":"Ответ","text":"Десяти капель хватит на две банки."}],"keyNote":null},{"number":10,"title":"Куб и квадрат числа x","question":"Про число x известно, что x³ < 64 < x². Тогда","options":[{"text":"0 < x < 64"},{"text":"−8 < x < 4"},{"text":"−4 < x < 8"},{"text":"x < −8"},{"text":"такого числа x не существует"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"Неравенство x³ < 64 означает x < 4. Второе неравенство x² > 64 даёт x < −8 или x > 8."},{"title":"Ответ","text":"Пересечение условий оставляет только x < −8."}],"keyNote":null},{"number":11,"title":"Площадь параллелограмма","question":"Фигура на рисунке образована двумя квадратами, треугольником, площадь которого равна 8 см², и закрашенным параллелограммом. Чему равна площадь этого параллелограмма?","options":[{"text":"15 см²"},{"text":"16 см²"},{"text":"18 см²"},{"text":"20 см²"},{"text":"21 см²"}],"condition":{"src":"assets/grades-9-10/2012/task-11.svg","width":186,"height":138,"pixelWidth":256,"pixelHeight":190,"alt":"Два квадрата разного размера, треугольник между ними и серый параллелограмм сверху"},"answer":1,"points":4,"review":[{"title":"Решение","text":"У треугольника и параллелограмма есть по две стороны, выходящие из общей вершины. У каждой пары соответствующие стороны — соседние стороны одного квадрата, поэтому их длины равны и направления отличаются на 90°."},{"title":"Ответ","text":"Синусы углов между выбранными сторонами равны, поэтому параллелограмм имеет вдвое большую площадь, чем треугольник. Получаем 16 см²."}],"keyNote":null},{"number":12,"title":"Число из нулей и единиц","question":"Маша изучает натуральные числа, которые делятся на 72 и имеют в своей десятичной записи только нули и единицы. Сколько цифр в самом маленьком из таких чисел?","options":[{"text":"9"},{"text":"11"},{"text":"12"},{"text":"13"},{"text":"14"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Делимость на 72 означает делимость на 8 и на 9. Из составленных из нулей и единиц трёхзначных окончаний на 8 делится только 000."},{"title":"Ответ","text":"Сумма цифр должна делиться на 9, значит, единиц не меньше девяти. Девять единиц и три нуля на конце уже дают подходящее число. В нём 12 цифр."}],"keyNote":null},{"number":13,"title":"Кто смотрит в окно","question":"В семье пятеро мужчин: Иван Сидорович, Сидор Иванович, Сидор Петрович, Пётр Сидорович и Пётр Петрович. Один из них сейчас смотрит в окно, его отец спит, брат читает книгу, а сыновья ушли гулять. Как зовут того, кто смотрит в окно?","options":[{"text":"Иван Сидорович"},{"text":"Сидор Иванович"},{"text":"Сидор Петрович"},{"text":"Пётр Сидорович"},{"text":"Пётр Петрович"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Решение","text":"Мужчина должен иметь брата с тем же отчеством и двух сыновей с отчеством от его имени. Иван не годится, потому что Иванович в списке один. Сидор Иванович не имеет брата. У Сидора Петровича сыном был бы Пётр Сидорович, тогда для роли его отца не остаётся подходящего Петра."},{"title":"Ответ","text":"Если в окно смотрит Пётр Сидорович, его брат Иван Сидорович, отец Сидор Иванович, а сыновья Сидор Петрович и Пётр Петрович. Все пять ролей согласуются."}],"keyNote":null},{"number":14,"title":"Периметр по диагонали","question":"Две стороны четырёхугольника равны 1 и 7. Одна из диагоналей, длина которой равна 3, делит его на два равнобедренных треугольника. Чему равен периметр этого четырёхугольника?","options":[{"text":"12"},{"text":"14"},{"text":"16"},{"text":"18"},{"text":"20"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Решение","text":"Стороны 1 и 7 не могут входить вместе в треугольник с диагональю 3, так как 1 + 3 < 7. Значит, они лежат в разных частях."},{"title":"Ответ","text":"Равнобедренные треугольники могут иметь стороны только 1, 3, 3 и 7, 7, 3. Диагональ 3 входит в обе части, но не в периметр. Внешние стороны дают 1 + 3 + 7 + 7 = 18."}],"keyNote":null},{"number":15,"title":"Равенства степеней","question":"Натуральные числа a и b таковы, что a + b = 2012. Какое из следующих равенств возможно при некотором натуральном k?","options":[{"text":"2ᵃ · 3ᵇ = 12ᵏ"},{"text":"2ᵃ · 3ᵇ = 18ᵏ"},{"text":"2ᵃ · 3ᵇ = 36ᵏ"},{"text":"2ᵃ · 3ᵇ = 72ᵏ"},{"text":"2ᵃ · 3ᵇ = 48ᵏ"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Для каждого основания разложим его на степени 2 и 3. Суммы показателей для 12, 18, 36, 72, 48 равны соответственно 3, 3, 4, 5 и 5."},{"title":"Ответ","text":"Эта сумма, умноженная на k, должна дать 2012. Число 2012 делится из перечисленных только на 4. Основание 36 подходит при k = 503."}],"keyNote":null},{"number":16,"title":"Изменения двух чисел","question":"Число x отрицательно, а число y положительно. Что не может произойти, если x увеличить, а y — уменьшить?","options":[{"text":"x + y увеличится"},{"text":"x/y уменьшится"},{"text":"y/x уменьшится"},{"text":"y − x уменьшится"},{"text":"x − y уменьшится"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Решение","text":"Так как x возрастает, а y убывает, разность x − y обязательно возрастает. Поэтому она не может уменьшиться."},{"title":"Ответ","text":"Сумма может возрасти, если x вырос сильнее. Оба частных могут убыть по отдельности, например −4/4 переходит в −3/2, а 4/(−4) в 3/(−1). Разность y − x всегда убывает."}],"keyNote":null},{"number":17,"title":"Квадрат из треугольников","question":"На какое наименьшее число тупоугольных треугольников можно разрезать квадрат?","options":[{"text":"4"},{"text":"5"},{"text":"6"},{"text":"7"},{"text":"это невозможно сделать"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Углы частей в четырёх исходных углах квадрата не могут быть тупыми. Все остальные углы в сумме дают (n − 2)·180° при n частях. На стороне квадрата или в точке примыкания к прямой стороне другого треугольника учитывается 180°, внутри в обычном узле — 360°."},{"title":"Проверка","text":"В точке с суммой 180° может быть лишь один тупой угол, а с суммой 360° — не более трёх. При n ≤ 5 общий запас не превосходит 540°. Даже сочетание 360° и 180° даёт лишь четыре тупых угла, и при меньшем n их тоже не хватит для всех частей."},{"title":"Ответ","text":"Проведём диагональ квадрата. В каждой половине выберем точку на высоте из прямого угла, чуть выше середины гипотенузы и ближе к прямому углу. Соединим её с тремя вершинами. Все три угла в выбранной точке больше 90°, поэтому две половины дают шесть тупоугольных треугольников."}],"keyNote":null},{"number":18,"title":"Чётность произведения","question":"Какое из утверждений А–Г неверно?","options":[{"text":"произведение любых двух нечётных чисел — нечётное число"},{"text":"произведение любых двух нечётных функций — нечётная функция"},{"text":"произведение любых двух чётных чисел — чётное число"},{"text":"произведение любых двух чётных функций — чётная функция"},{"text":"все утверждения А–Г верны"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"При замене x на −x каждая из двух нечётных функций меняет знак. В произведении два минуса уничтожаются."},{"title":"Ответ","text":"Произведение нечётных функций в общем случае чётное. Например, x × x = x². Поэтому утверждение Б неверно."}],"keyNote":null},{"number":19,"title":"Крестики в таблице","question":"В некоторых клетках таблицы 10×10 поставлены крестики так, что каждый из них — единственный либо в своей строке, либо в своём столбце. Какое наибольшее число крестиков может быть в такой таблице?","options":[{"text":"10"},{"text":"15"},{"text":"18"},{"text":"19"},{"text":"99"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Сопоставим строкам и столбцам вершины графа, а крестикам — рёбра. По условию у каждого ребра хотя бы один конец имеет степень 1. Значит, каждая непустая связная часть графа — звезда."},{"title":"Проверка","text":"Если есть хотя бы две части, рёбер не больше 20 − 2 = 18. Если часть только одна, звезда имеет не более десяти рёбер."},{"title":"Ответ","text":"Поставим девять крестиков в первой строке, минуя первый столбец, и девять в первом столбце, минуя первую строку. Получаем 18."}],"keyNote":null},{"number":20,"title":"Ордината вершины параболы","question":"Разность корней квадратного уравнения x² + bx + c = 0 — чётное число. Чему может равняться ордината вершины параболы y = x² + bx + c?","options":[{"text":"−2"},{"text":"−3"},{"text":"−4"},{"text":"−5"},{"text":"−6"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Если корни различаются на 2k, их середина — абсцисса вершины. Подстановка в произведение (x − x₁)(x − x₂) даёт значение −k²."},{"title":"Ответ","text":"Из предложенных ординат квадратом с минусом является только −4. Например, такую вершину даёт парабола y = x² − 4."}],"keyNote":null},{"number":21,"title":"Покупка мёда","question":"Винни-Пух пошёл в магазин за мёдом. Цена одного горшочка — 1 фунт, но при покупке n горшочков (n < 100) покупатель получает скидку n %. Когда Винни вернулся домой, Кристофер Робин посмотрел на его покупку и сказал: «Глупенький мой мишка! Ты ухитрился заплатить за мёд наибольшую возможную сумму денег!». Сколько фунтов заплатил Винни-Пух?","options":[{"text":"10"},{"text":"15"},{"text":"20"},{"text":"25"},{"text":"50"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"n горшочков со скидкой n % стоят n(1 − n/100) фунтов."},{"title":"Ответ","text":"Преобразуем в 25 − (n − 50)²/100. Максимум при n = 50, уплачено 25 фунтов."}],"keyNote":null},{"number":22,"title":"Суммы в столбцах","question":"Числа от 1 до 120 выписаны в 15 строк, как показано на рисунке. В каком из столбцов (считая слева) сумма чисел самая большая?","options":[{"text":"1"},{"text":"4"},{"text":"5"},{"text":"7"},{"text":"13"}],"condition":{"src":"assets/grades-9-10/2012/task-22.svg","width":351,"height":195,"pixelWidth":487,"pixelHeight":270,"alt":"В первой строке 1, во второй — 2 и 3, в третьей — 4, 5 и 6. Дальнейшие строки содержат на одно число больше предыдущей"},"answer":2,"points":5,"review":[{"title":"Решение","text":"В столбце j стоят числа j + r(r − 1)/2 для строк r от j до 15. При переходе к столбцу j + 1 исчезает число j(j + 1)/2, зато оставшиеся 15 − j чисел растут на единицу."},{"title":"Ответ","text":"Разность сумм равна 15 − j − j(j + 1)/2. Она положительна при j до 4 и отрицательна с j = 5. Наибольшая сумма в пятом столбце."}],"keyNote":null},{"number":23,"title":"Отношение кратных чисел","question":"Про натуральные числа m и n известно, что каждое из них делится на числа 2² · 3³ · 5 и 2³ · 3, а каждое из чисел 2⁵ · 3⁷ · 5³ и 2⁴ · 3⁶ · 5² делится на m и n. Чему равно наибольшее возможное отношение чисел m и n?","options":[{"text":"2² · 3⁴ · 5²"},{"text":"2 · 3³"},{"text":"2² · 3 · 5²"},{"text":"2 · 3² · 5"},{"text":"2 · 3³ · 5"}],"condition":null,"answer":4,"points":5,"review":[{"title":"Решение","text":"Числа m и n должны быть кратны наименьшему общему кратному первых двух чисел, то есть 2³·3³·5. Одновременно они должны делить наибольший общий делитель двух больших чисел, равный 2⁴·3⁶·5²."},{"title":"Ответ","text":"Эти нижняя и верхняя границы сами допустимы. Для максимума отношения берём их в числитель и знаменатель в порядке убывания. Получаем 2·3³·5."}],"keyNote":null},{"number":24,"title":"Треугольник катится вокруг","question":"Правильный треугольник «катится» вокруг квадрата (см. рисунок справа). Какую траекторию опишет отмеченная точка, прежде чем и она, и весь треугольник вернутся в исходное положение?","options":[{"image":"assets/grades-9-10/2012/task-24-answer-1.svg","description":"Четыре пересекающиеся петли, квадрат в центре","pixelWidth":235,"pixelHeight":235},{"image":"assets/grades-9-10/2012/task-24-answer-2.webp","description":"Замкнутая линия с четырьмя выпуклыми дугами","pixelWidth":255,"pixelHeight":255},{"image":"assets/grades-9-10/2012/task-24-answer-3.svg","description":"Две петли, квадрат в их пересечении","pixelWidth":235,"pixelHeight":235},{"image":"assets/grades-9-10/2012/task-24-answer-4.svg","description":"Окружность с квадратом внутри","pixelWidth":163,"pixelHeight":166},{"image":"assets/grades-9-10/2012/task-24-answer-5.svg","description":"Четыре закрученные дуги вокруг квадрата","pixelWidth":233,"pixelHeight":235}],"condition":{"src":"assets/grades-9-10/2012/task-24.svg","width":328,"height":106,"pixelWidth":500,"pixelHeight":162,"alt":"Показаны последовательные повороты равностороннего треугольника вокруг углов неподвижного квадрата. Одна вершина треугольника отмечена точкой"},"answer":0,"points":5,"review":[{"title":"Решение","text":"При переходе на следующую сторону квадрата треугольник поворачивается вокруг угла на 210°. Это 120° до продолжения вдоль прямого края и ещё 90° из-за поворота края квадрата."},{"title":"Проверка","text":"После одного обхода все положения фигур повторяются, но отметка переходит на другую вершину. Для исходной отметки нужны три обхода. Около каждого угла она один раз стоит в центре поворота и два раза чертит дуги радиуса в сторону треугольника."},{"title":"Ответ","text":"Эти две дуги начинаются под углом 60° друг к другу и вместе занимают 270° — три четверти круга снаружи квадрата. Четыре такие пересекающиеся дуги дают рисунок А."}],"keyNote":null},{"number":25,"title":"Дробь с числителем 1","question":"Дробь 28/33 хотят представить в виде суммы нескольких дробей, числители которых равны 1. При каком наименьшем числе слагаемых это возможно?","options":[{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"},{"text":"28"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Если два единичных слагаемых не больше 1/3, их сумма не больше 2/3. Поэтому в разложении на два слагаемых нужно взять 1/2. Остаток 23/66 не имеет вида 1/k."},{"title":"Ответ","text":"Три слагаемых подходят, поскольку 28/33 = 1/2 + 1/3 + 1/66. Минимум три."}],"keyNote":null},{"number":26,"title":"Сколько прямых пересекаются","question":"На плоскости нарисовано несколько прямых. Рядом с каждой прямой написано число прямых, которые ее пересекают. Среди написанных чисел имеется не менее четырёх различных, два из которых — это 6 и 7. Сколько прямых нарисовано?","options":[{"text":"9"},{"text":"10"},{"text":"13"},{"text":"15"},{"text":"невозможно определить"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Пусть всего N прямых. Прямая, принадлежащая группе из k параллельных, пересекает ровно N − k других, значит, есть четыре разные величины k. Сумма четырёх различных положительных размеров не меньше 10."},{"title":"Проверка","text":"Значения пересечений 6 и 7 означают группы N − 6 и N − 7. При N ≥ 11 ещё две группы дают как минимум 1 + 2, так что N ≥ (N − 6) + (N − 7) + 3 = 2N − 10, противоречие."},{"title":"Ответ","text":"Остаётся N = 10. Группы параллельных прямых размеров 1, 2, 3, 4 дают нужные числа пересечений."}],"keyNote":null},{"number":27,"title":"Удвоенный угол треугольника","question":"В треугольнике длины сторон равны a, b и c, а угол, лежащий против стороны b, вдвое больше угла, лежащего против стороны a. Тогда обязательно","options":[{"text":"a² + c² = b²"},{"text":"b² + bc = a²"},{"text":"c² + ab = a²"},{"text":"a² + ac = b²"},{"text":"каждое из соотношений А–Г может быть нарушено"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"Если угол напротив a равен α, по теореме синусов b/a = sin 2α/sin α = 2 cos α. По теореме косинусов 2bc cos α = b² + c² − a²."},{"title":"Проверка","text":"Подстановка даёт b²(c − a) = a(c² − a²) = a(c − a)(c + a). При c ≠ a сокращаем и получаем b² = a² + ac."},{"title":"Ответ","text":"При c = a два угла α равны, а третий равен 2α, поэтому он прямой. Тогда b² = 2a², то же равенство."}],"keyNote":null},{"number":28,"title":"Точки с заданной площадью","question":"На рисунке OA = 6 см, OB = 4 см. Каково множество всех точек P, лежащих в первой четверти, для которых площадь четырёхугольника PAOB равна 24 см²?","options":[{"image":"assets/grades-9-10/2012/task-28-answer-1.svg","description":"Отрезок от (0, 8) до (12, 0)","pixelWidth":208,"pixelHeight":212},{"image":"assets/grades-9-10/2012/task-28-answer-2.svg","description":"Отрезок от (0, 12) до (8, 0)","pixelWidth":168,"pixelHeight":212},{"image":"assets/grades-9-10/2012/task-28-answer-3.svg","description":"Отрезок от (0, 10) до (10, 0)","pixelWidth":183,"pixelHeight":212},{"image":"assets/grades-9-10/2012/task-28-answer-4.svg","description":"Дуга от (0, 5) до (5, 0)","pixelWidth":139,"pixelHeight":212},{"image":"assets/grades-9-10/2012/task-28-answer-5.svg","description":"Кривая от (0, 10) до (10, 0)","pixelWidth":191,"pixelHeight":212}],"condition":{"src":"assets/grades-9-10/2012/task-28.svg","width":208,"height":154,"pixelWidth":288,"pixelHeight":213,"alt":"Точки A и B лежат на положительных полуосях x и y. Точка P вместе с A, O и B образует серый четырёхугольник"},"answer":0,"points":5,"review":[{"title":"Решение","text":"Пусть P = (x; y). Диагональ OP делит фигуру на треугольники OAP и OBP, площадями 6y/2 и 4x/2."},{"title":"Ответ","text":"Нужна прямая 3y + 2x = 24 в первой четверти. Она пересекает оси в (0; 8) и (12; 0), что соответствует варианту А."}],"keyNote":null},{"number":29,"title":"Хорошие тройки чисел","question":"Назовём тройку различных чисел, выбранных из множества {1, 2, 3, 4, 5, 6}, хорошей, если никакая пара чисел из этой тройки не имеет сумму 7. Коля перемножил числа в каждой хорошей тройке, а потом сложил полученные произведения. Какое число он получил?","options":[{"text":"7²"},{"text":"7³"},{"text":"3⁶"},{"text":"3⁷"},{"text":"6³"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Запрещённые пары — (1, 6), (2, 5) и (3, 4). Каждая хорошая тройка берёт ровно одно число из каждой пары."},{"title":"Ответ","text":"Сумма произведений равна (1 + 6)(2 + 5)(3 + 4) по распределительному закону. Получаем 7³."}],"keyNote":null},{"number":30,"title":"Сечение куба","question":"Из 27 одинаковых маленьких кубиков сложили куб. Через середину его диагонали провели плоскость, перпендикулярную этой диагонали. Сколько маленьких кубиков пересекла эта плоскость?","options":[{"text":"17"},{"text":"18"},{"text":"19"},{"text":"20"},{"text":"21"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Решение","text":"Возьмём ребро маленького кубика за единицу. Большой куб имеет координаты от 0 до 3 по каждой оси, а плоскость через середину диагонали задаётся x + y + z = 4,5."},{"title":"Проверка","text":"Для малого кубика с нижними координатами i, j, k сумма меняется от i + j + k до i + j + k + 3. Пересечение есть при сумме 2, 3 или 4."},{"title":"Ответ","text":"Не подходят кубики с суммами 0, 1, 5, 6. Их соответственно 1, 3, 3 и 1. Пересечены 27 − 8 = 19 кубиков."}],"keyNote":null}]}];
'use strict';

(() => {
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const visual = globalThis.KenguruVisual;
  const cyrillicAnswers = 'АБВГД';

  function circleComparison(step, frame) {
    const outline = '#54877e';
    const fill = ['#347d75', '#43998c', '#60a99d', '#2e807c'];
    const ink = '#172e34';
    const radius = 43;
    const quarter = 'M0 0H43A43 43 0 0 0 0 -43Z';
    if (step === 1) {
      const opacity = .25 + .75 * visual.reveal(frame);
      return visual.svg(`<rect x="225" y="20" width="190" height="190" rx="3" fill="#f1f6ee" stroke="${outline}" stroke-width="2"/>
        <path d="M320 115H415A95 95 0 0 0 320 20Z" fill="${fill[0]}" opacity="${opacity}"/>
        <path d="M320 123V130M415 123V130M320 126H415" fill="none" stroke="${ink}" stroke-width="2"/>
        <text x="367.5" y="154" fill="${ink}" font-size="17" text-anchor="middle">радиус</text>`,
      'Радиус четверти круга равен половине стороны квадрата', '0 0 640 230', 'worked-scene');
    }
    if (step !== 2) return null;

    const far = radius;
    const offsets = [
      [[-far, far], [-far, -far], [far, -far], [far, far]],
      [[0, 0], [0, 0], [0, 0], [0, 0]],
      [[-far, 0], [-far, 0], [far, 0], [far, 0]],
      [[0, far], [-far, -far], [far, -far], [0, far]],
    ];
    const groups = offsets.map((pieces, index) => {
      const x = index % 2 === 0 ? 222 : 418;
      const y = index < 2 ? 95 : 254;
      const start = index * .38;
      const turn = index === 1 ? 0 : 180 * visual.reveal((frame - start) * 2.5);
      const remaining = 1 - visual.reveal((frame - start - 1.2) * 1.15);
      const paths = pieces.map(([dx, dy], piece) =>
        `<path d="${quarter}" fill="${fill[piece]}" stroke="#fffefa"
          stroke-width=".6" transform="translate(${x + dx * remaining} ${y + dy * remaining}) rotate(${90 * piece + turn})"/>`
      ).join('');
      return `<rect x="${x - radius}" y="${y - radius}" width="${radius * 2}" height="${radius * 2}"
        fill="#f1f6ee" stroke="${outline}" stroke-width="1.6"/>${paths}
        <text x="${x - 96}" y="${y + 6}" fill="${ink}" font-size="20" text-anchor="middle">${cyrillicAnswers[index]}</text>`;
    });
    return visual.svg(groups.join(''), 'Четыре четверти каждого рисунка складываются в целый круг',
      '102 0 432 348', 'worked-scene');
  }

  function shadeCells(step, frame) {
    if (step !== 2) return null;
    const alreadyShaded = [2, 4, 7, 9];
    const newlyShaded = [0, 1];
    const cells = Array.from({length: 12}, (_, index) => {
      const x = 90 + index % 4 * 42;
      const y = 20 + Math.floor(index / 4) * 42;
      const change = newlyShaded.indexOf(index);
      const opacity = alreadyShaded.includes(index) ? 1 : change < 0 ? 0 : visual.reveal(frame * 2 - change * .65);
      return `<rect x="${x}" y="${y}" width="42" height="42" fill="#fff"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="#202020" opacity="${opacity}"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="none" stroke="#202020" stroke-width="1.2"/>`;
    });
    return visual.svg(cells.join(''), 'В двух белых клетках верхней строки появляется чёрная заливка',
      '65 6 218 154', 'worked-scene');
  }

  const editions = [...(globalThis.KENGURU_GRADES_7_8 ?? []), ...(globalThis.KENGURU_JUNIOR_SENIOR ?? [])];
  for (const edition of editions) {
    const answerLetters = [...(edition.answerLetters ?? cyrillicAnswers)];
    const {id, year, label, grades, tasksUrl, answersUrl, solutionUrl, cards} = edition;
    const lessons = [];
    const scenes = [];

    for (const {number, title, question, questionNote, options, condition, answer, points, review, keyNote} of cards) {
      const hasReview = review.length > 0;
      const choiceImages = options.map(option => option.image);
      const choices = options.map(option => option.text ?? '');
      const answerLetter = answerLetters[answer];
      const steps = [['Условие', 'Условие задачи', '']];
      for (const [index, stage] of review.entries()) {
        const final = index === review.length - 1;
        steps.push([final ? 'Ответ' : 'Шаг ' + (index + 1), stage.title, stage.text]);
      }
      if (!hasReview) {
        steps.push(['Ответ', 'Проверка по ключу', keyNote ?? (answerLetter ? 'Правильный вариант — ' + answerLetter + '.' : 'Сверь решение с ответом в PDF.')]);
      }

      lessons.push({
        number, title, short: title, question, questionNote, points, answer, choices, choiceImages,
        choiceLayout: {condition, options}, conditionImage: condition?.src, conditionAlt: condition?.alt,
        hideIntroText: true, paperEdition: !hasReview, showCompletedStep: hasReview,
        officialValueKey: answer === null,
        steps,
      });

      const keyedAnswer = visual.answerScene({letter: answerLetter, value: choices[answer]});
      scenes.push((step, frame) => {
        if (!step) return '';
        if (!hasReview) return keyedAnswer;
        const stage = review[step - 1];
        const animation = id === '2026-7-8' && number === 1 ? circleComparison(step, frame)
          : id === '2017-2' && number === 6 ? shadeCells(step, frame) : null;
        return animation ?? (visual.workedScene(stage, frame)
          || (step === review.length ? keyedAnswer : ''));
      });
    }
    archive[id] = {id, year, label, grades, answerLetters, sources: {tasksUrl, answersUrl, solutionUrl}, lessons, scenes};
  }
})();

register((globalThis.KENGURU_ARCHIVE["2012-9-10"] ?? [].concat(globalThis.KENGURU_ARCHIVE[2012] ?? []).find(edition => edition.id === "2012-9-10")), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
